const root = $json.body || $json || {};
const data = root.data || root;
const key = data.key || {};
const msg = data.message || root.message || {};
const documentMessage = msg.documentMessage || msg.documentWithCaptionMessage?.message?.documentMessage || msg.ephemeralMessage?.message?.documentMessage || null;
const extended = msg.extendedTextMessage || msg.ephemeralMessage?.message?.extendedTextMessage || null;
const remoteJid = String(key.remoteJid || data.remoteJid || data.from || root.from || data.sender || root.sender || '').trim();
const isGroup = /@g\.us$/i.test(remoteJid);
let phone = String(data.number || data.phone || root.number || remoteJid.split('@')[0] || data.sender || root.sender || '').replace(/\D/g, '');
if (phone.startsWith('0') && phone.length > 11) phone = phone.replace(/^0+/, '');
const caption = String(documentMessage?.caption || msg.imageMessage?.caption || msg.videoMessage?.caption || '').trim();
const text = String(
  data.text || root.text || data.body || root.body || msg.conversation || extended?.text || caption || ''
).trim();
const messageId = String(key.id || data.messageId || data.id || root.messageId || root.id || '').trim() || `${phone}:${Date.now()}`;
const fromMe = Boolean(key.fromMe || data.fromMe || root.fromMe);
const filename = String(documentMessage?.fileName || documentMessage?.filename || data.fileName || data.filename || 'fatura.pdf').trim() || 'fatura.pdf';
const mimetype = String(documentMessage?.mimetype || data.mimetype || data.mimeType || '').trim();
const isDocument = Boolean(documentMessage || data.messageType === 'documentMessage' || data.messageType === 'document');
const isPdf = Boolean(isDocument && (/pdf/i.test(mimetype) || /\.pdf$/i.test(filename)));
const isText = Boolean(text && !isPdf);
return [{ json: {
  phone,
  remote_jid: remoteJid,
  message_text: text,
  message_id: messageId,
  push_name: data.pushName || root.pushName || data.push_name || '',
  instance: root.instance || data.instance || $env.EVOLUTION_INSTANCE_NAME || '',
  from_me: fromMe,
  is_group: isGroup,
  is_document: isDocument,
  is_pdf: isPdf,
  is_text: isText,
  filename,
  mimetype,
  caption,
  media_message: msg,
  is_valid_user_message: Boolean(phone && !fromMe && !isGroup && (text || isPdf)),
  should_reply_unsupported: Boolean(phone && !fromMe && !isGroup),
  current_date: new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
  raw: root
}}];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
let parsed;
try {
  const cleaned = cleanJsonContent($json.output ?? $json.text ?? $json.response ?? '');
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = { intent: 'help', confidence: 0, reply_text: 'Posso te ajudar com categorias: listar compras sem categoria, categorizar uma compra ou aprender uma regra de estabelecimento.' };
}
const conversation = $('Resolve AcerttaPay User').first().json.conversation || {};
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = { channel: 'whatsapp', instance: $('Normalize Evolution Payload').first().json.instance, message_id: $('Normalize Evolution Payload').first().json.message_id, raw_text: $('Normalize Evolution Payload').first().json.message_text };
let endpoint = '/api/automation/v1/categories/options';
let body = { phone, source };
if (conversation.state === 'awaiting_category_learning_confirmation') {
  endpoint = '/api/automation/v1/categories/conversations/reply';
  body = { phone, source, reply: { raw_text: source.raw_text } };
} else if (parsed.intent === 'show_uncategorized_purchases') {
  endpoint = '/api/automation/v1/categories/uncategorized';
  body = { phone, source, month: parsed.month, year: parsed.year, period: parsed.period, limit: 12 };
} else if (parsed.intent === 'set_purchase_category') {
  endpoint = '/api/automation/v1/categories/apply-to-purchase';
  body = { phone, source, purchase_id: parsed.purchase_id, purchase_hint: parsed.purchase_hint, category_id: parsed.category_id, category_hint: parsed.category_hint, create_category: parsed.create_category === true };
} else if (parsed.intent === 'set_merchant_category_rule') {
  endpoint = '/api/automation/v1/categories/create-merchant-rule';
  body = { phone, source, merchant_hint: parsed.merchant_hint, merchant_label: parsed.merchant_hint, pattern: parsed.merchant_hint, category_id: parsed.category_id, category_hint: parsed.category_hint, create_category: parsed.create_category === true, apply_existing: parsed.apply_existing === true };
} else if (parsed.intent === 'out_of_scope') {
  return [{ json: { send_direct: true, reply_text: parsed.reply_text || 'Essa parte ainda não é comigo. Aqui eu cuido de categorias e aprendizado de compras. 🏷️' } }];
} else if (parsed.intent === 'help') {
  return [{ json: { send_direct: true, reply_text: parsed.reply_text || '🏷️ Posso te ajudar com categorias. Exemplos:\n• *compras sem categoria*\n• *compra #123 é Alimentação*\n• *sempre classifique iFood como Alimentação*' } }];
}
return [{ json: { endpoint, body, idempotency_key: `whatsapp-category:${source.instance}:${source.message_id}` } }];
